{"path": "src/application/ValidateNickname.js", "content": "/**
 * @file Use case: валидация никнейма.
 * Чистая функция — без DOM, без localStorage.
 */

const NICKNAME_MIN = 1;
const NICKNAME_MAX = 16;

/**
 * @param {string} raw
 * @returns {{ valid: boolean, nickname: string, error: string|null }}
 */
export function validateNickname(raw) {
  if (typeof raw !== 'string') {
    return { valid: false, nickname: '', error: 'Никнейм должен быть строкой.' };
  }

  let nickname = raw.trim().replace(/\s+/g, ' ');

  // Удаляем управляющие символы
  nickname = nickname.replace(/[\x00-\x1F\x7F]/g, '');

  if (nickname.length < NICKNAME_MIN) {
    return { valid: false, nickname: '', error: 'Никнейм не может быть пустым.' };
  }

  if (nickname.length > NICKNAME_MAX) {
    return { valid: false, nickname: '', error: `Никнейм не длиннее ${NICKNAME_MAX} символов.` };
  }

  return { valid: true, nickname, error: null };
}"}

