{"path": "src/application/SaveScore.js", "content": "/**
 * @file Use case: сохранение результата.
 * Зависит от порта IWritableLeaderboard (DIP).
 */

import { validateNickname } from './ValidateNickname.js';
import { ScoreEntry } from '../domain/ScoreEntry.js';
import { getGameConfig } from '../domain/GameConfig.js';

export class SaveScore {
  /**
   * @param {import('../domain/ports.js').IWritableLeaderboard} leaderboardRepo
   */
  constructor(leaderboardRepo) {
    this._repo = leaderboardRepo;
  }

  /**
   * @param {string} gameId
   * @param {string} rawNickname
   * @param {number} score
   * @returns {{ success: boolean, error: string|null }}
   */
  async execute(gameId, rawNickname, score) {
    const config = getGameConfig(gameId);
    if (!config) {
      return { success: false, error: `Неизвестная игра: ${gameId}` };
    }

    const validation = validateNickname(rawNickname);
    if (!validation.valid) {
      return { success: false, error: validation.error };
    }

    const scoreInt = Math.floor(Number(score));
    if (!Number.isFinite(scoreInt) || scoreInt < 0) {
      return { success: false, error: 'Некорректный счёт.' };
    }
    if (scoreInt > config.maxReasonableScore) {
      return { success: false, error: `Счёт превышает допустимый максимум (${config.maxReasonableScore}).` };
    }

    const entry = new ScoreEntry(gameId, validation.nickname, scoreInt);

    try {
      await this._repo.saveScore(entry);
      return { success: true, error: null };
    } catch (err) {
      return { success: false, error: 'Не удалось сохранить результат. Попробуйте позже.' };
    }
  }
}"}

