{"content": "/**
 * @file Реализация портов IReadableLeaderboard и IWritableLeaderboard
 * на базе localStorage.
 */

import { ScoreEntry } from '../domain/ScoreEntry.js';
import { getGameConfig } from '../domain/GameConfig.js';

const SCORES_PREFIX = 'arcade.scores.';
const BEST_PREFIX = 'arcade.best.';
const DEFAULT_LIMIT = 10;

export class LocalStorageLeaderboardRepository {
  /**
   * @param {number} [maxEntriesPerGame=DEFAULT_LIMIT]
   */
  constructor(maxEntriesPerGame = DEFAULT_LIMIT) {
    this._maxEntries = maxEntriesPerGame;
  }

  /** @returns {boolean} */
  _isAvailable() {
    try {
      const key = `__test_${Date.now()}`;
      localStorage.setItem(key, '1');
      localStorage.removeItem(key);
      return true;
    } catch {
      return false;
    }
  }

  /** @param {string} gameId @returns {string} */
  _scoresKey(gameId) {
    return SCORES_PREFIX + gameId;
  }

  /** @param {string} gameId @returns {string} */
  _bestKey(gameId) {
    return BEST_PREFIX + gameId;
  }

  /**
   * @param {string} gameId
   * @returns {ScoreEntry[]}
   */
  _readScores(gameId) {
    if (!this._isAvailable()) throw new Error('localStorage недоступен');
    const raw = localStorage.getItem(this._scoresKey(gameId));
    if (!raw) return [];
    try {
      const arr = JSON.parse(raw);
      if (!Array.isArray(arr)) return [];
      return arr
        .map((item) => {
          try {
            return ScoreEntry.fromRaw(item);
          } catch {
            return null;
          }
        })
        .filter(Boolean);
    } catch {
      throw new Error('Ошибка чтения таблицы лидеров');
    }
  }

  /**
   * @param {string} gameId
   * @param {ScoreEntry[]} entries
   */
  _writeScores(gameId, entries) {
    if (!this._isAvailable()) throw new Error('localStorage недоступен');
    const sorted = [...entries]
      .sort((a, b) => b.score - a.score)
      .slice(0, this._maxEntries);
    localStorage.setItem(this._scoresKey(gameId), JSON.stringify(sorted.map((e) => e.toRaw())));

    // Обновляем лучший результат
    const best = sorted.length > 0 ? sorted[0].score : 0;
    localStorage.setItem(this._bestKey(gameId), String(best));
  }

  // --- IReadableLeaderboard ---

  /**
   * @param {string} gameId
   * @param {number} [limit]
   * @returns {Promise<ScoreEntry[]>}
   */
  async getTopScores(gameId, limit) {
    const entries = this._readScores(gameId);
    return entries.slice(0, limit || this._maxEntries);
  }

  /**
   * @param {string} gameId
   * @returns {Promise<number>}
   */
  async getBestScore(gameId) {
    if (!this._isAvailable()) return 0;
    const key = this._bestKey(gameId);
    const val = localStorage.getItem(key);
    if (val === null) return 0;
    const num = parseInt(val, 10);
    return Number.isFinite(num) ? num : 0;
  }

  // --- IWritableLeaderboard ---

  /**
   * @param {ScoreEntry} entry
   * @returns {Promise<void>}
   */
  async saveScore(entry) {
    const entries = this._readScores(entry.gameId);
    entries.push(entry);
    this._writeScores(entry.gameId, entries);
  }
}", "path": "src/infrastructure/LocalStorageLeaderboardRepository.js"}

