/**
 * @file Инфраструктура: менеджер ввода (клавиатура, мышь, тач).
 * Абстрагирует события ввода для всех игр.
 */

export class InputManager {
  constructor() {
    /** @type {Set<string>} */
    this._pressedKeys = new Set();
    /** @type {Set<string>} */
    this._justPressedKeys = new Set();
    /** @type {Array<{x: number, y: number}>} */
    this._clicks = [];
    /** @type {Array<{x: number, y: number}>} */
    this._touches = [];

    this._onKeyDown = (e) => {
      if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'KeyW', 'KeyA', 'KeyS', 'KeyD', 'Escape', 'KeyP', 'Enter'].includes(e.code)) {
        e.preventDefault();
      }
      if (!this._pressedKeys.has(e.code)) {
        this._justPressedKeys.add(e.code);
      }
      this._pressedKeys.add(e.code);
    };

    this._onKeyUp = (e) => {
      this._pressedKeys.delete(e.code);
    };

    this._onClick = (e) => {
      this._clicks.push({ x: e.clientX, y: e.clientY });
    };

    this._onTouchStart = (e) => {
      for (const touch of e.changedTouches) {
        this._touches.push({ x: touch.clientX, y: touch.clientY });
      }
      // Имитируем пробел для тача (удобно для Flappy Bird)
      if (!this._pressedKeys.has('Space')) {
        this._justPressedKeys.add('Space');
      }
      this._pressedKeys.add('Space');
    };

    this._onTouchEnd = () => {
      this._pressedKeys.delete('Space');
    };

    this._bound = false;
  }

  /** Привязать слушателей к window */
  bind() {
    if (this._bound) return;
    this._bound = true;
    window.addEventListener('keydown', this._onKeyDown);
    window.addEventListener('keyup', this._onKeyUp);
    window.addEventListener('click', this._onClick);
    window.addEventListener('touchstart', this._onTouchStart, { passive: true });
    window.addEventListener('touchend', this._onTouchEnd);
  }

  /** Отвязать слушателей */
  unbind() {
    this._bound = false;
    window.removeEventListener('keydown', this._onKeyDown);
    window.removeEventListener('keyup', this._onKeyUp);
    window.removeEventListener('click', this._onClick);
    window.removeEventListener('touchstart', this._onTouchStart);
    window.removeEventListener('touchend', this._onTouchEnd);
    this._pressedKeys.clear();
    this._justPressedKeys.clear();
    this._clicks = [];
    this._touches = [];
  }

  /** @param {string} code */
  isPressed(code) {
    return this._pressedKeys.has(code);
  }

  /** @param {string} code */
  isJustPressed(code) {
    return this._justPressedKeys.has(code);
  }

  /** Очистить флаги «только что нажато» (вызывать в конце каждого кадра) */
  clearFrame() {
    this._justPressedKeys.clear();
    this._clicks = [];
    this._touches = [];
  }

  /** @returns {{ x: number, y: number }[]} */
  getClicks() {
    return this._clicks;
  }

  /** @returns {{ x: number, y: number }[]} */
  getTouches() {
    return this._touches;
  }
}

