export class RafLoop {
  /**
   * @param {object} options
   * @param {number} [options.fixedDt=1/60]
   * @param {Function} [options.onUpdate] — (dt: number) => void
   * @param {Function} [options.onRender] — (alpha: number) => void
   */
  constructor({ fixedDt = 1 / 60, onUpdate, onRender } = {}) {
    this._fixedDt = fixedDt;
    this._onUpdate = onUpdate || (() => {});
    this._onRender = onRender || (() => {});

    this._accumulator = 0;
    this._lastTime = 0;
    this._running = false;
    this._rafId = null;
  }

  /** Запустить цикл */
  start() {
    if (this._running) return;
    this._running = true;
    this._accumulator = 0;
    this._lastTime = performance.now();
    this._tick(this._lastTime);
  }

  /** Остановить цикл */
  stop() {
    this._running = false;
    if (this._rafId !== null) {
      cancelAnimationFrame(this._rafId);
      this._rafId = null;
    }
  }

  /** @param {number} now */
  _tick(now) {
    if (!this._running) return;

    let frameTime = (now - this._lastTime) / 1000;
    this._lastTime = now;

    // Защита от больших лагов
    if (frameTime > 0.25) frameTime = 0.25;

    this._accumulator += frameTime;

    while (this._accumulator >= this._fixedDt) {
      this._onUpdate(this._fixedDt);
      this._accumulator -= this._fixedDt;
    }

    const alpha = this._accumulator / this._fixedDt;
    this._onRender(alpha);

    this._rafId = requestAnimationFrame((t) => this._tick(t));
  }
