{"content": "/**
 * @file Flappy Bird — реализация IGame
 */

import { getGameConfig } from '../domain/GameConfig.js';

const CONFIG = getGameConfig('flappy');

const GRAVITY = 1200;        // пикселей/с²
const FLAP_VELOCITY = -350;  // пикселей/с
const PIPE_WIDTH = 60;
const PIPE_GAP = 150;
const PIPE_SPEED = 200;      // пикселей/с
const PIPE_SPAWN_INTERVAL = 1.8; // секунд
const GROUND_HEIGHT = 60;
const BIRD_SIZE = 28;

/**
 * @implements {import('../domain/ports.js').IGame}
 */
export class FlappyGame {
  /**
   * @param {HTMLCanvasElement} canvas
   */
  constructor(canvas) {
    this._canvas = canvas;
    this._ctx = canvas.getContext('2d');
    this._input = null;
    this._loop = null;
    this._gameOverCallback = null;

    this._state = 'idle'; // idle | ready | playing | gameover
    this._score = 0;
    this._bird = { x: 80, y: 0, vy: 0 };
    this._pipes = [];
    this._pipeTimer = 0;
    this._groundY = 0;
  }

  // --- IGame ---

  mount(canvas, input, loop) {
    this._canvas = canvas;
    this._ctx = canvas.getContext('2d');
    this._input = input;
    this._loop = loop;
  }

  start() {
    this._reset();
    this._state = 'ready';
    this._loop.start();
  }

  pause() {
    this._loop.stop();
  }

  resume() {
    this._loop.start();
  }

  dispose() {
    this._loop.stop();
    this._gameOverCallback = null;
    this._input = null;
    this._loop = null;
  }

  /**
   * @param {(score: number) => void} cb
   */
  onGameOver(cb) {
    this._gameOverCallback = cb;
  }

  // --- internal ---

  _reset() {
    this._score = 0;
    this._bird = {
      x: 80,
      y: this._canvas.height / 2,
      vy: 0,
    };
    this._pipes = [];
    this._pipeTimer = 0;
    this._groundY = this._canvas.height - GROUND_HEIGHT;
    this._state = 'idle';
  }

  /**
   * @param {number} dt — fixed timestep
   */
  _update(dt) {
    if (this._state === 'ready') {
      // Ожидание первого нажатия
      if (this._input.isJustPressed('Space') || this._input.isJustPressed('Enter') || this._input.getClicks().length > 0 || this._input.getTouches().length > 0) {
        this._state = 'playing';
        this._bird.vy = FLAP_VELOCITY;
      }
      // Птичка парит на месте
      this._bird.y = this._canvas.height / 2 + Math.sin(Date.now() / 300) * 10;
      return;
    }

    if (this._state !== 'playing') return;

    // Ввод
    if (this._input.isJustPressed('Space') || this._input.isJustPressed('Enter') || this._input.getClicks().length > 0 || this._input.getTouches().length > 0) {
      this._bird.vy = FLAP_VELOCITY;
    }

    // Гравитация
    this._bird.vy += GRAVITY * dt;
    this._bird.y += this._bird.vy * dt;

    // Генерация труб
    this._pipeTimer += dt;
    if (this._pipeTimer >= PIPE_SPAWN_INTERVAL) {
      this._pipeTimer = 0;
      this._spawnPipe();
    }

    // Движение труб
    for (let i = this._pipes.length - 1; i >= 0; i--) {
      const p = this._pipes[i];
      p.x -= PIPE_SPEED * dt;

      // Подсчёт очков
      if (!p.scored && p.x + PIPE_WIDTH < this._bird.x) {
        p.scored = true;
        this._score++;
      }

      // Удаление за экраном
      if (p.x + PIPE_WIDTH < 0) {
        this._pipes.splice(i, 1);
      }
    }

    // Коллизии: столкновение с трубами или выход за границы
    const birdRect = {
      x: this._bird.x - BIRD_SIZE / 2,
      y: this._bird.y - BIRD_SIZE / 2,
      w: BIRD_SIZE,
      h: BIRD_SIZE,
    };

    for (const p of this._pipes) {
      if (this._rectsOverlap(birdRect, p.topRect) || this._rectsOverlap(birdRect, p.bottomRect)) {
        this._gameOver();
        return;
      }
    }

    // Пол/потолок
    if (this._bird.y - BIRD_SIZE / 2 < 0 || this._bird.y + BIRD_SIZE / 2 > this._groundY) {
      this._gameOver();
    }
  }

  _render() {
    const ctx = this._ctx;
    const w = this._canvas.width;
    const h = this._canvas.height;

    // Небо
    ctx.fillStyle = '#70c5ce';
    ctx.fillRect(0, 0, w, h);

    // Трубы
    ctx.fillStyle = '#73bf2e';
    for (const p of this._pipes) {
      ctx.fillRect(p.topRect.x, p.topRect.y, p.topRect.w, p.topRect.h);
      ctx.fillRect(p.bottomRect.x, p.bottomRect.y, p.bottomRect.w, p.bottomRect.h);
      // Ободки
      ctx.fillStyle = '#558b2f';
      ctx.fillRect(p.topRect.x - 4, p.topRect.y + p.topRect.h - 20, p.topRect.w + 8, 20);
      ctx.fillRect(p.bottomRect.x - 4, p.bottomRect.y, p.bottomRect.w + 8, 20);
      ctx.fillStyle = '#73bf2e';
    }

    // Земля
    ctx.fillStyle = '#ded895';
    ctx.fillRect(0, this._groundY, w, GROUND_HEIGHT);
    ctx.fillStyle = '#c4a44a';
    ctx.fillRect(0, this._groundY, w, 3);

    // Птица
    const bx = this._bird.x;
    const by = this._bird.y;
    ctx.save();
    ctx.translate(bx, by);
    const angle = Math.max(-0.5, Math.min(0.5, this._bird.vy * 0.001));
    ctx.rotate(angle);
    ctx.fillStyle = '#f5c842';
    ctx.beginPath();
    ctx.arc(0, 0, BIRD_SIZE / 2, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#e65100';
    ctx.beginPath();
    ctx.moveTo(BIRD_SIZE / 2, 0);
    ctx.lineTo(BIRD_SIZE / 2 + 10, -4);
    ctx.lineTo(BIRD_SIZE / 2 + 10, 4);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = '#000';
    ctx.beginPath();
    ctx.arc(6, -4, 3, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();

    // Счёт
    ctx.fillStyle = '#fff';
    ctx.font = 'bold 36px monospace';
    ctx.strokeStyle = '#000';
    ctx.lineWidth = 4;
    ctx.textAlign = 'center';
    ctx.strokeText(String(this._score), w / 2, 50);
    ctx.fillText(String(this._score), w / 2, 50);

    // Ready / Game Over — сообщения
    if (this._state === 'ready') {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(w / 2 - 120, h / 2 - 30, 240, 60);
      ctx.fillStyle = '#fff';
      ctx.font = 'bold 20px sans-serif';
      ctx.fillText('Нажмите ПРОБЕЛ', w / 2, h / 2 + 8);
    } else if (this._state === 'gameover') {
      ctx.fillStyle = 'rgba(0,0,0,0.6)';
      ctx.fillRect(w / 2 - 100, h / 2 - 50, 200, 100);
      ctx.fillStyle = '#ff4444';
      ctx.font = 'bold 28px sans-serif';
      ctx.fillText('GAME OVER', w / 2, h / 2 - 10);
      ctx.fillStyle = '#fff';
      ctx.font = '18px sans-serif';
      ctx.fillText(`Счёт: ${this._score}`, w / 2, h / 2 + 30);
    }
  }

  _spawnPipe() {
    const w = this._canvas.width;
    const minTop = 60;
    const maxTop = this._groundY - PIPE_GAP - 60;
    const topH = minTop + Math.random() * (maxTop - minTop);
    const bottomY = topH + PIPE_GAP;

    this._pipes.push({
      x: w,
      topRect: { x: w, y: 0, w: PIPE_WIDTH, h: topH },
      bottomRect: { x: w, y: bottomY, w: PIPE_WIDTH, h: this._groundY - bottomY },
      scored: false,
    });
  }

  _rectsOverlap(a, b) {
    return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
  }

  _gameOver() {
    if (this._state === 'gameover') return;
    this._state = 'gameover';
    this._loop.stop();
    if (this._gameOverCallback) {
      this._gameOverCallback(this._score);
    }
  }
}", "path": "src/games/FlappyGame.js"}

