          ctx.fillRect(offsetX + gx * BLOCK_SIZE + 1, offsetY + gy * BLOCK_SIZE + 1, BLOCK_SIZE - 2, BLOCK_SIZE - 2);
        }
      }
      ctx.globalAlpha = 1;

      for (let r = 0; r < cells.length; r++) {
        for (let c = 0; c < cells[r].length; c++) {
          if (!cells[r][c]) continue;
          const py = y + r;
          const px = x + c;
          if (py < 0) continue;
          ctx.fillStyle = color;
          ctx.fillRect(offsetX + px * BLOCK_SIZE + 1, offsetY + py * BLOCK_SIZE + 1, BLOCK_SIZE - 2, BLOCK_SIZE - 2);
          ctx.fillStyle = 'rgba(255,255,255,0.2)';
          ctx.fillRect(offsetX + px * BLOCK_SIZE + 1, offsetY + py * BLOCK_SIZE + 1, BLOCK_SIZE - 2, 4);
        }
      }
    }

    // Счёт и уровень
    ctx.fillStyle = '#fff';
    ctx.font = 'bold 20px monospace';
    ctx.textAlign = 'right';
    ctx.fillText(`Очки: ${this._score}`, w - 10, 30);
    ctx.fillText(`Уровень: ${this._level}`, w - 10, 58);
    ctx.fillText(`Линии: ${this._linesCleared}`, w - 10, 86);

    // Подсказка слева
    ctx.textAlign = 'left';
    ctx.font = '14px sans-serif';
    ctx.fillStyle = '#888';
    ctx.fillText('← → движение', 10, h - 60);
    ctx.fillText('↑ поворот', 10, h - 40);
    ctx.fillText('Пробел сброс', 10, h - 20);
  }

  _gameOver() {
    if (this._state === 'gameover') return;
    this._state = 'gameover';
    this._loop.stop();

    // Показываем GAME OVER
    const ctx = this._ctx;
    const w = this._canvas.width;
    const h = this._canvas.height;
    ctx.fillStyle = 'rgba(0,0,0,0.7)';
    ctx.fillRect(w / 2 - 120, h / 2 - 40, 240, 80);
    ctx.fillStyle = '#ff4444';
    ctx.font = 'bold 32px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('GAME OVER', w / 2, h / 2 + 6);
    ctx.fillStyle = '#fff';
    ctx.font = '18px sans-serif';
    ctx.fillText(`Счёт: ${this._score}`, w / 2, h / 2 + 34);

    if (this._gameOverCallback) {
      this._gameOverCallback(this._score);
    }
  }
}

