  }

  dispose() {
    this._loop.stop();
    this._gameOverCallback = null;
    this._input = null;
    this._loop = null;
  }

  onGameOver(cb) {
    this._gameOverCallback = cb;
  }

  // --- internal ---

  _reset() {
    const w = this._canvas.width;
    const h = this._canvas.height;
    this._score = { player: 0, ai: 0 };
    this._paddle.y = h / 2 - PADDLE_HEIGHT / 2;
    this._aiPaddle.y = h / 2 - PADDLE_HEIGHT / 2;
    this._ball.x = w / 2;
    this._ball.y = h / 2;
    this._ball.vx = BALL_SPEED_INITIAL;
    this._ball.vy = 0;
    this._serving = true;
    this._serveTimer = 0;
  }

  _startServe() {
    this._serving = true;
    this._serveTimer = 0;
    this._ball.x = this._canvas.width / 2;
    this._ball.y = this._canvas.height / 2;
    this._ball.vx = 0;
    this._ball.vy = 0;
  }

  _launchBall() {
    const angle = (Math.random() * 0.8 - 0.4); // от -0.4 до 0.4 рад
    const dir = Math.random() > 0.5 ? 1 : -1;
    const speed = BALL_SPEED_INITIAL + (this._score.player + this._score.ai) * BALL_SPEED_INCREASE;
    this._ball.vx = Math.cos(angle) * speed * dir;
    this._ball.vy = Math.sin(angle) * speed;
    this._serving = false;
  }

  _update(dt) {
    if (this._state !== 'playing') return;
    const w = this._canvas.width;
    const h = this._canvas.height;

    // Сервис
    if (this._serving) {
      this._serveTimer += dt;
      if (this._serveTimer >= 1.0) {
        this._launchBall();
      }
      // Пока сервис — двигать ракетку можно
      this._updatePlayerPaddle(dt);
      this._updateAIPaddle(dt);
      return;
    }

    // Движение ракеток
    this._updatePlayerPaddle(dt);
    this._updateAIPaddle(dt);

    // Движение мяча
    this._ball.x += this._ball.vx * dt;
    this._ball.y += this._ball.vy * dt;

    // Отскок от верха/низа
    if (this._ball.y - BALL_SIZE / 2 < 0) {
      this._ball.y = BALL_SIZE / 2;
      this._ball.vy = -this._ball.vy;
    }
    if (this._ball.y + BALL_SIZE / 2 > h) {
      this._ball.y = h - BALL_SIZE / 2;
      this._ball.vy = -this._ball.vy;
