      this._ball.x - BALL_SIZE / 2 < px + PADDLE_WIDTH &&
      this._ball.x - BALL_SIZE / 2 > px &&
      this._ball.y > this._paddle.y &&
      this._ball.y < this._paddle.y + PADDLE_HEIGHT &&
      this._ball.vx < 0
