      this._ball.x + BALL_SIZE / 2 > aiX &&
      this._ball.x + BALL_SIZE / 2 < aiX + PADDLE_WIDTH &&
      this._ball.y > this._aiPaddle.y &&
      this._ball.y < this._aiPaddle.y + PADDLE_HEIGHT &&
