    if (this._ball.x - BALL_SIZE / 2 > w) {
      // Игрок забил
      this._score.player++;
      if (this._score.player >= WIN_SCORE) {
        this._gameOver();
        return;
      }
      this._startServe();
    }
  }

  _updatePlayerPaddle(dt) {
    const h = this._canvas.height;
    if (this._input.isPressed('ArrowUp') || this._input.isPressed('KeyW')) {
      this._paddle.y -= PADDLE_SPEED * dt;
