    ctx.fillStyle = '#ff4466';
    ctx.shadowColor = '#ff4466';
    ctx.shadowBlur = 10;
    ctx.fillRect(w - 20 - PADDLE_WIDTH, this._aiPaddle.y, PADDLE_WIDTH, PADDLE_HEIGHT);
