import { FlappyGame } from './FlappyGame.js';
import { TetrisGame } from './TetrisGame.js';
import { PongGame } from './PongGame.js';
import { SkirmishGame } from './SkirmishGame.js';

/** @type {Object<string, new (canvas: HTMLCanvasElement) => import('../domain/ports.js').IGame>} */
export const GAMES_REGISTRY = {
  flappy: FlappyGame,
  tetris: TetrisGame,
  pong: PongGame,
  skirmish: SkirmishGame,
};

/**
 * @param {string} gameId
 * @param {HTMLCanvasElement} canvas
 * @returns {import('../domain/ports.js').IGame | null}
 */
export function createGameInstance(gameId, canvas) {
  const GameClass = GAMES_REGISTRY[gameId];
  if (!GameClass) return null;
  return new GameClass(canvas);
}

