import { getAllGameConfigs } from '../domain/GameConfig.js';
import { createGameInstance } from '../games/GamesRegistry.js';
import { RafLoop } from '../infrastructure/RafLoop.js';
import { InputManager } from '../infrastructure/InputManager.js';
import { GetBestScore } from '../application/GetBestScore.js';
import { LocalStorageLeaderboardRepository } from '../infrastructure/LocalStorageLeaderboardRepository.js';

export class GameHub {
  /** @param {HTMLElement} rootEl */
  constructor(rootEl) {
    this._root = rootEl;
    this._currentGame = null;
    this._currentInput = null;
    this._currentLoop = null;
    this._canvas = null;
    this._leaderboardRepo = new LocalStorageLeaderboardRepository();
    this._getBestScore = new GetBestScore(this._leaderboardRepo);
    this._onGameOver = null;
  }

  /** Инициализация хаба */
  async init() {
    this._renderHub();
  }

  /** Отрисовка хаба */
  async _renderHub() {
    const configs = getAllGameConfigs();

    // Получаем рекорды для всех игр
    const bestScores = {};
    for (const cfg of configs) {
      const result = await this._getBestScore.execute(cfg.id);
      bestScores[cfg.id] = result.error === null ? result.bestScore : null;
    }

    this._root.innerHTML = `
      <div class="hub">
        <h1 class="hub__title">🎮 Аркадный портал</h1>
        <div class="hub__grid">
          ${configs.map((cfg) => `
            <div class="hub__card" data-game-id="${cfg.id}">
              <div class="hub__card-icon">${cfg.icon}</div>
              <div class="hub__card-title">${cfg.title}</div>
              <div class="hub__card-desc">${this._escapeHtml(cfg.description)}</div>
              <div class="hub__card-best">
                ${bestScores[cfg.id] !== null
                  ? `🏆 Рекорд: <strong>${bestScores[cfg.id]}</strong>`
                  : '⏳ Рекорд недоступен'}
              </div>
              <div class="hub__card-actions">
                <button class="btn btn-play" data-action="play">Играть</button>
                <button class="btn btn-leaderboard" data-action="leaderboard">Лидеры</button>
              </div>
            </div>
          `).join('')}
        </div>
      </div>
    `;

    // Подписка на клики
    this._root.querySelectorAll('.hub__card').forEach((card) => {
      const gameId = card.dataset.gameId;
      card.querySelector('[data-action="play"]').addEventListener('click', () => {
        this._startGame(gameId);
      });
      card.querySelector('[data-action="leaderboard"]').addEventListener('click', () => {
        this._showLeaderboard(gameId);
      });
    });
  }

  /**
   * Запустить игру
   * @param {string} gameId
   */
  async _startGame(gameId) {
    // Создаём canvas
    const wrapper = document.createElement('div');
    wrapper.className = 'game-wrapper';
    this._root.innerHTML = '';
    this._root.appendChild(wrapper);

    const canvas = document.createElement('canvas');
    canvas.className = 'game-canvas';
    canvas.width = Math.min(800, window.innerWidth - 20);
    canvas.height = Math.min(600, window.innerHeight - 120);
    wrapper.appendChild(canvas);

    // Кнопка «Назад»
    const toolbar = document.createElement('div');
    toolbar.className = 'game-toolbar';
    const backBtn = document.createElement('button');
    backBtn.className = 'btn btn-back';
    backBtn.textContent = '← К списку игр';
    backBtn.addEventListener('click', () => {
      if (this._currentGame) {
        this._currentGame.dispose();
        this._currentGame = null;
      }
      if (this._currentInput) {
        this._currentInput.unbind();
        this._currentInput = null;
      }
      this._currentLoop = null;
      this._renderHub();
    });
    toolbar.appendChild(backBtn);
    wrapper.prepend(toolbar);

    // Инфраструктура
    const input = new InputManager();
    input.bind();

    const loop = new RafLoop({
      onUpdate: (dt) => {
        if (this._currentGame) {
          // Метод update может отсутствовать — используем хак: сохраняем game для _update
          // Каждая игра сама обрабатывает dt в своём методе _update
        }
      },
      onRender: () => {
        if (this._currentGame) {
          // Каждая игра сама рендерит
        }
      },
    });

    // Создаём экземпляр игры
    const game = createGameInstance(gameId, canvas);
    if (!game) {
      this._renderHub();
      return;
    }

    this._currentGame = game;
    this._currentInput = input;
    this._currentLoop = loop;

    // Сохраняем ссылки на update/render для игр
    // Игры используют loop.start()/stop() сами, поэтому передаём им loop
    game.mount(canvas, input, loop);

    // Заменяем update/render loop на вызовы игры
    loop._onUpdate = (dt) => {
      if (game._update) game._update(dt);
      input.clearFrame();
    };
    loop._onRender = () => {
      if (game._render) game._render();
    };

    game.onGameOver((score) => {
      this._showGameOver(gameId, score);
    });

    game.start();
  }

  /**
   * Экран Game Over
   * @param {string} gameId
   * @param {number} score
   */
  async _showGameOver(gameId, score) {
    const result = await this._getBestScore.execute(gameId);
    const bestScore = result.error === null ? result.bestScore : null;

    const overlay = document.createElement('div');
    overlay.className = 'game-over-overlay';

    overlay.innerHTML = `
      <div class="game-over-modal">
        <h2 class="game-over-title">Игра завершена!</h2>
        <div class="game-over-score">${score}</div>
        <div class="game-over-best">
          ${bestScore !== null ? `🏆 Лучший результат: ${bestScore}` : ''}
        </div>
        <div class="game-over-nickname">
          <input type="text" id="nickname-input" class="nickname-input" placeholder="Введите никнейм (1-16 символов)" maxlength="16" />
          <div id="nickname-error" class="nickname-error"></div>
          <button id="save-score-btn" class="btn btn-save">Отправить в таблицу лидеров</button>
        </div>
        <div class="game-over-actions">
          <button id="restart-btn" class="btn btn-primary">🔄 Заново</button>
          <button id="hub-btn" class="btn btn-secondary">🏠 К списку игр</button>
          <button id="leaderboard-btn" class="btn btn-secondary">📋 Таблица лидеров</button>
        </div>
      </div>
    `;

    document.body.appendChild(overlay);

    // Сохранение
    const nicknameInput = overlay.querySelector('#nickname-input');
    const saveBtn = overlay.querySelector('#save-score-btn');
    const errorEl = overlay.querySelector('#nickname-error');

    saveBtn.addEventListener('click', async () => {
      const { SaveScore } = await import('../application/SaveScore.js');
      const saveScore = new SaveScore(this._leaderboardRepo);
      const result2 = await saveScore.execute(gameId, nicknameInput.value, score);
      if (result2.success) {
        errorEl.textContent = '✅ Результат сохранён!';
        errorEl.style.color = '#4caf50';
        saveBtn.disabled = true;
        nicknameInput.disabled = true;
      } else {
        errorEl.textContent = result2.error;
        errorEl.style.color = '#ff4444';
      }
    });

    // Restart
    overlay.querySelector('#restart-btn').addEventListener('click', () => {
      overlay.remove();
      if (this._currentGame) {
        this._currentGame.dispose();
        this._currentGame = null;
      }
      if (this._currentInput) {
        this._currentInput.unbind();
        this._currentInput = null;
      }
      this._currentLoop = null;
      this._startGame(gameId);
    });

    // To hub
    overlay.querySelector('#hub-btn').addEventListener('click', () => {
      overlay.remove();
      if (this._currentGame) {
        this._currentGame.dispose();
        this._currentGame = null;
      }
      if (this._currentInput) {
        this._currentInput.unbind();
        this._currentInput = null;
      }
      this._currentLoop = null;
      this._renderHub();
    });

    // Leaderboard
    overlay.querySelector('#leaderboard-btn').addEventListener('click', () => {
      overlay.remove();
      if (this._currentGame) {
        this._currentGame.dispose();
        this._currentGame = null;
      }
      if (this._currentInput) {
        this._currentInput.unbind();
        this._currentInput = null;
      }
      this._currentLoop = null;
      this._showLeaderboard(gameId);
    });
  }

  /**
   * Показать таблицу лидеров
   * @param {string} gameId
   */
  async _showLeaderboard(gameId) {
    const config = getAllGameConfigs().find((c) => c.id === gameId);
    const { GetLeaderboard } = await import('../application/GetLeaderboard.js');
    const getLeaderboard = new GetLeaderboard(this._leaderboardRepo);
    const result = await getLeaderboard.execute(gameId);

    this._root.innerHTML = `
      <div class="leaderboard-page">
        <h1 class="leaderboard-title">
          ${config ? config.icon : '📋'} ${config ? config.title : 'Игра'} — Лидеры
        </h1>
        ${result.error
          ? `<div class="leaderboard-error">${this._escapeHtml(result.error)}</div>`
          : result.entries.length === 0
            ? `<div class="leaderboard-empty">Пока нет записей. Сыграйте и станьте первым!</div>`
            : `<table class="leaderboard-table">
                <thead>
                  <tr>
                    <th>#</th>
                    <th>Никнейм</th>
                    <th>Счёт</th>
                    <th>Дата</th>
                  </tr>
                </thead>
                <tbody>
                  ${result.entries.map((entry, i) => `
                    <tr class="${i === 0 ? 'leaderboard-first' : ''}">
                      <td>${i + 1}</td>
                      <td>${this._escapeHtml(entry.nickname)}</td>
                      <td class="leaderboard-score">${entry.score}</td>
                      <td class="leaderboard-date">${new Date(entry.playedAt).toLocaleDateString()}</td>
                    </tr>
                  `).join('')}
                </tbody>
              </table>`
        }
        <div class="leaderboard-actions">
          <button id="back-to-hub-btn" class="btn btn-primary">← К списку игр</button>
        </div>
      </div>
    `;

    this._root.querySelector('#back-to-hub-btn').addEventListener('click', () => {
      this._renderHub();
    });
  }

  /**
   * @param {string} str
   * @returns {string}
   */
  _escapeHtml(str) {
    const div = document.createElement('div');
    div.textContent = str;
    return div.innerHTML;
  }
}", "path": "src/presentation/GameHub.js"}

