/**
 * @file Главная точка входа — инициализация портала.
 */

import { GameHub } from './presentation/GameHub.js';
import { RafLoop } from './infrastructure/RafLoop.js';
import { InputManager } from './infrastructure/InputManager.js';

const appEl = document.getElementById('app');

if (!appEl) {
  throw new Error('Элемент #app не найден в DOM');
}

const hub = new GameHub(appEl);
hub.init().catch((err) => {
  console.error('Ошибка инициализации хаба:', err);
  appEl.innerHTML = `
    <div style="text-align:center;padding:40px;color:#ff4444;">
      <h2>Произошла ошибка при загрузке портала</h2>
      <p>${err.message}</p>
      <button onclick="location.reload()" style="margin-top:16px;padding:10px 20px;font-size:16px;">
        Перезагрузить
      </button>
    </div>
  `;
});

// Глобальный перехват ошибок для graceful degradation
window.addEventListener('error', (e) => {
  console.warn('Глобальная ошибка:', e.message);
});

